namespace GeetaStudio.Api;

internal static class CreationPage
{
    internal const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create a private learning pack</title>
<style>body{font:18px/1.5 system-ui;max-width:850px;margin:auto;padding:24px;background:#fff9ef;color:#252525}label{display:block;margin:14px 0}input,textarea,select,button{font:inherit;padding:8px;max-width:100%}iframe{width:100%;height:600px;border:1px solid #777}section{margin:24px 0}#status{white-space:pre-wrap}</style>
<h1>Create a private learning pack</h1><p>Choose a reviewed template and a fictional nickname. This is personalized fiction with attributed learning content. No public link is created.</p>
<label>Workspace <select id="tenant"></select></label><button id="load">Open studio</button><label>Managed profile <select id="profile"></select></label><label>Template <select id="template"></select></label><p id="estimate"></p><label>Fictional nickname <input id="nickname" maxlength="30" value="Learner"></label><label>Theme <select id="theme"></select></label><label>Your reflection <textarea id="reflection" maxlength="1000"></textarea></label>
<section><h2>Optional owned material</h2><label>Plain PNG or UTF-8 text <input id="file" type="file" accept="image/png,text/plain"></label><label>Description <input id="alt" maxlength="200"></label><label><input id="consent" type="checkbox"> I own this material and authorize its use for this managed profile. It depicts no real person.</label><button id="upload">Add private material</button></section>
<button id="submit">Create</button><p>Credits are reserved at submission and charged once for accepted local output. Queued cancellation releases credits. Editing is included; deleting completed work removes private content without refunding accepted work.</p><label>Your creations <select id="creation"></select></label><button id="refresh">Refresh progress</button><button id="edit">Save reflection changes</button><button id="review">Approve private export</button><button id="export">Download pack</button><button id="cancel">Cancel queued work</button><button id="delete">Delete private creation</button><p id="status" role="status" aria-live="polite"></p><iframe id="preview" title="Private creation preview" sandbox=""></iframe>
<script>
const $=x=>document.getElementById(x);let templates=[],current=null,uploads=[],pendingSubmit=null,busy=false;const base=()=>'/api/v1/customer/tenants/'+encodeURIComponent($('tenant').value)+'/create';const op=()=>crypto.randomUUID();const input=()=>({nickname:$('nickname').value,theme:$('theme').value,reflection:$('reflection').value});
async function api(path,body){let r=await fetch(base()+path,{credentials:'same-origin',method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());return r.status===204?null:r.json()}
const choose=(el,rows,label)=>{el.replaceChildren();for(let x of rows){let o=document.createElement('option');o.value=x.id;o.textContent=label(x);el.append(o)}};function selected(){let t=templates.find(x=>x.id===$('template').value);choose($('theme'),t?t.settings.themes.map(x=>({id:x})):[],x=>x.id);$('estimate').textContent=t?'Estimated '+t.settings.credits+' credits · '+t.settings.format+' · English · Private':''}
async function refresh(){let rows=await api('/creations');let id=$('creation').value;choose($('creation'),rows,x=>x.state+' · version '+x.version);if(rows.some(x=>x.id===id))$('creation').value=id;current=rows.find(x=>x.id===$('creation').value);$('preview').srcdoc=current?.html||'';$('status').textContent=current?current.state+' · '+current.outcome+' · charged '+current.chargedCredits+' · queue position '+current.queuePosition+' · '+current.cleanup:'No creations yet'}
const run=f=>async()=>{if(busy)return;busy=true;const buttons=document.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await f()}catch(e){$('status').textContent=e.message}finally{busy=false;buttons.forEach(b=>b.disabled=false)}};$('load').onclick=run(async()=>{templates=await api('/templates');choose($('template'),templates,x=>x.settings.key+' · '+x.settings.format);let r=await fetch('/api/v1/customer/tenants/'+encodeURIComponent($('tenant').value)+'/profiles',{credentials:'same-origin'});if(!r.ok)throw Error(await r.text());choose($('profile'),await r.json(),x=>x.alias+' · '+x.ageBand);selected();await refresh()});$('template').onchange=selected;
$('upload').onclick=run(async()=>{let f=$('file').files[0];if(!f||f.size>1048576)throw Error('Select a file up to 1 MiB');let b=new Uint8Array(await f.arrayBuffer()),s='';for(let v of b)s+=String.fromCharCode(v);let id=await api('/uploads',{operationId:op(),profileId:$('profile').value,mediaType:f.type,content:btoa(s),altText:$('alt').value,rights:'Owned',consent:$('consent').checked,realPerson:false});uploads.push(id);$('status').textContent='Private material added'});
$('submit').onclick=run(async()=>{let data={templateId:$('template').value,profileId:$('profile').value,input:input(),uploadIds:uploads};let signature=JSON.stringify(data);if(!pendingSubmit||pendingSubmit.signature!==signature)pendingSubmit={signature,request:{operationId:op(),...data}};let id=await api('/creations',pendingSubmit.request);await refresh();$('creation').value=id;await refresh();pendingSubmit=null;uploads=[]});$('refresh').onclick=run(refresh);$('creation').onchange=run(async()=>{await refresh();if(current?.input){$('template').value=current.templateId;selected();$('nickname').value=current.input.nickname;$('theme').value=current.input.theme;$('reflection').value=current.input.reflection}});
$('edit').onclick=run(async()=>{await api('/creations/'+current.id+'/edit',{operationId:op(),rowVersion:current.rowVersion,input:input()});await refresh()});$('review').onclick=run(async()=>{await api('/creations/'+current.id+'/review',{operationId:op(),rowVersion:current.rowVersion,decision:'Approve',evidence:'fixture:owner-private-preview',mode:'Fixture',sharingConsent:false});await refresh()});
$('export').onclick=run(async()=>{let a=document.createElement('a');a.href=base()+'/creations/'+current.id+'/download';a.download='private-pack.zip';a.click()});for(let action of ['cancel','delete'])$(action).onclick=run(async()=>{await api('/creations/'+current.id+'/'+action,{});await refresh()});
run(async()=>{let r=await fetch('/api/v1/customer/create/workspaces',{credentials:'same-origin'});if(!r.ok)throw Error(await r.text());choose($('tenant'),await r.json(),x=>x.name);const requested=new URLSearchParams(location.search).get('workspace');if(requested&&Array.from($('tenant').options).some(x=>x.value===requested))$('tenant').value=requested;$('status').textContent=$('tenant').options.length?'Choose a workspace and open the studio.':'Create your local account first, then an administrator can configure reviewed templates.'})();
</script></html>
""";
}
